   "title": "2025年B市旅游业发展情况",
   "body": "2025年，B市接待游客12840万人次，比上年增长18.6%；实现旅游总收入1462.5亿元，增长24.3%。\n其中，接待入境游客186.4万人次，增长62.5%；实现入境旅游收入12.86亿美元，增长58.2%。\n年末全市共有A级旅游景区218家，比上年末增加12家；其中5A级景区6家，4A级景区57家。\n全市星级饭店平均客房出租率为68.4%，比上年提高4.7个百分点；平均房价486元/间夜，上涨5.8%。",
