   "difficulty": 3,
   "materialId": null,
   "stem": "填入横线部分最恰当的一句是：\n一项好的制度，应当让守信者受益、失信者受限。如果失信的成本过低，________。",
   "options": [
    "守信就会变成一种昂贵的选择",
    "监管部门的压力就会减轻",
    "信用体系建设就无从谈起",
    "市场秩序就会更加混乱"
   ],
   "answer": 0,
   "explain": "横线前是“失信成本过低”，按逻辑推理，失信划算则守信相对吃亏，B 最贴合“成本—收益”的对比，且与首句“让守信者受益”形成反面呼应。A 过于笼统，且“更加混乱”缺少比较对象；C 与文意相反；D“无从谈起”程度过重。",
   "optionNotes": [
    "正确。失信成本低→守信代价高。",
    "失信成本低会加大监管压力，方向相反。",
    "程度过重，且偏离“成本”这一核心。",
    "表述笼统，未扣住“守信/失信”的成本对比。"
   ],
   "method": "语句填空在尾句时，要与全文核心概念（守信/失信、成本）保持话题一致",
   "traps": [
    "选语义正确但程度过重的选项",
    "忽略话题一致性"
   ],
