   "stem": "沉没成本是指已经发生且无法收回的支出。理性决策时应只考虑未来的成本与收益，而不应被沉没成本左右。\n根据上述定义，下列属于“受沉没成本影响”的是：",
   "options": [
    "小王比较三家店的价格后，选择了最便宜的一家购买",
    "小张因项目前景不佳，及时终止了已投入部分资金的计划",
    "小陈把闲置的旧电脑卖掉，用所得款项购买新设备",
    "小李买了电影票，看了20分钟发现很难看，但因为“票都买了”坚持看完"
   ],
   "answer": 3,
   "explain": "电影票钱已花且无法收回，属于沉没成本；小李因“票都买了”而继续投入时间，是被沉没成本左右，符合定义。B 是正常比价；C 是及时止损、不受沉没成本影响；D 是处置资产，均不符合。",
   "optionNotes": [
    "比价是面向未来的决策。",
    "及时终止恰是忽略沉没成本的表现。",
    "出售闲置资产与沉没成本无关。",
    "正确。票款不可收回，仍据此决定继续观看。"
   ],
   "method": "定义判断抓关键词：“已经发生、无法收回”+“因此影响后续决策”",
   "traps": [
    "把“已投入”当成沉没成本而不看是否影响决策",
    "忽略“理性决策应忽略”这一要件"
   ],
