   "difficulty": 2,
   "materialId": null,
   "stem": "机会成本是指为了得到某种东西而放弃的、价值最高的那一项选择。\n根据上述定义，下列涉及机会成本的是：",
   "options": [
    "小李的房子涨价了，账面资产增加50万元",
    "小赵把10万元存入银行，一年获得利息2000元",
    "小钱放弃年薪20万元的工作去读研，两年的学费与生活费共12万元",
    "小孙用优惠券购买了一件打折商品，节省了80元"
   ],
   "answer": 2,
   "explain": "机会成本强调“放弃的最高价值选择”。小钱读研放弃的年薪20万元/年即为机会成本（学费是显性成本，不属于机会成本定义的核心）。A 是利息收入；C 是节省支出；D 是资产增值，均未体现“放弃的最优选择”。",
   "optionNotes": [
    "是资产价格变动，未做选择。",
    "是实际收益，不是放弃的代价。",
    "正确。放弃的年薪即机会成本。",
    "是支出减少，不涉及放弃其他选择。"
   ],
   "method": "机会成本=放弃的最高价值选项，不是实际发生的支出",
   "traps": [
    "把学费等显性成本当机会成本",
    "把实际收益当机会成本"
   ],
