   "explain": "“只有P，才Q”翻译为 Q→P。已知小王获得晋升资格（Q），可推出通过考核（P），A 正确。C 是 P→Q，属于肯前推肯后，无效；D 是 ¬Q→¬P，属于否后推否前？原命题 Q→P 的逆否为 ¬P→¬Q，D 为 ¬Q→¬P，方向错误。",
   "optionNotes": [
    "与已知矛盾。",
    "把必要条件当充分条件（P→Q）。",
    "¬Q→¬P 是原命题的“否前”，无效。",
    "正确。Q→P，肯后推出肯前。"
   ],
   "method": "翻译推理：只有P才Q = Q→P；如果P那么Q = P→Q；逆否等价，否前肯后无效",
   "traps": [
    "把“只有…才…”当成“如果…那么…”",
    "混淆否前与逆否"
   ],
