   "stem": "甲、乙、丙三人分别来自北京、上海、广州，职业分别是教师、医生、工程师（一一对应）。已知：甲不是教师；来自北京的是医生；乙来自上海；丙不是工程师。\n由此可以推出乙的职业是：",
