   "stem": "一个圆的半径扩大到原来的2倍，它的面积扩大到原来的多少倍？",
   "options": [
    "2倍",
    "4倍",
    "5倍",
    "8倍"
   ],
   "answer": 1,
   "explain": "圆面积S=πr²。半径变为2r后，面积变为π(2r)²=4πr²，即扩大到原来的2²=4倍。",
   "optionNotes": [
    "半径扩大到k倍，面积按平方增长，不是线性增长。",
    "正确。圆面积S=πr²。半径变为2r后，面积变为π(2r)²=4πr²，即扩大到原来的2²=4倍。",
    "把“直径扩大”与“面积扩大”混为一谈。",
    "用了立方关系，平面图形的面积是平方关系。"
   ],
   "method": "相似图形：长度比=k，面积比=k²，体积比=k³",
   "traps": [
    "把半径倍数当面积倍数",
    "面积用立方关系"
   ],
