   "difficulty": 2,
   "materialId": null,
   "stem": "很多人以为，只要把更多的时间投入到工作中，就能获得更高的产出。然而研究发现，长时间工作会让人的注意力下降、错误率上升，反而拉低单位时间的产出。真正决定产出的，不是工作时长，而是单位时间内的专注程度。\n\n这段文字意在说明：",
   "options": [
    "提高专注度比延长工时更重要",
    "企业应减少员工的加班时间",
    "工作时长与产出并不总是正相关",
    "长时间工作会损害身体健康"
   ],
   "answer": 0,
   "explain": "文段先提出“投入更多时间→更高产出”的常见看法，用“然而”转折，指出长时间工作会拉低产出，最后一句点明“真正决定产出的是专注程度”。主旨落在“专注度比工时更重要”。A只停留在转折后的现象；B“身体健康”文段未提；D是过度推断。",
   "optionNotes": [
    "正确。尾句是主旨句。",
    "“减少加班”属于过度推断。",
    "只概括了转折后的现象，未落到“专注度”这一核心。",
    "“身体健康”文段没有提及。"
   ],
   "method": "中心理解：抓转折、因果、对策、尾句；选项必须包含主题词且不扩大不缩小",
