   "point": "yv-zhongxin",
   "difficulty": 2,
   "materialId": null,
   "stem": "城市里的老菜市场，往往被认为“脏乱差”，是城市更新的对象。但换一个角度看，菜市场也是城市中最具烟火气的公共空间：它承载着邻里交往、地方饮食和代际记忆。简单地拆掉重建，失去的不只是一个买菜的地方。\n\n这段文字主要强调：",
   "options": [
    "城市更新应尊重菜市场的公共价值",
    "菜市场是城市商业体系的重要组成部分",
    "居民对老菜市场有深厚感情",
    "老菜市场存在卫生和管理问题"
   ],
   "answer": 0,
   "explain": "文段用“但换一个角度看”转折，强调菜市场的公共空间价值，尾句“失去的不只是一个买菜的地方”进一步强化。主旨是城市更新应重视其价值。A是转折前内容；C“商业体系”未提；D只涉及感情，范围偏窄。",
   "optionNotes": [
    "正确。转折后是主旨。",
    "“商业体系”文段未提。",
    "只涉及一个方面，概括不全。",
    "转折前的内容，非重点。"
   ],
