   "id": "yv2-fr-03",
   "module": "yanyu",
   "point": "yv-zhongxin",
   "difficulty": 3,
   "materialId": null,
   "stem": "人工智能生成内容的技术门槛正在快速降低。过去需要专业团队才能完成的海报、短视频，如今普通人输入几句话就能生成。这带来便利的同时，也让“眼见为实”变得越来越难：一段以假乱真的视频，可能在几分钟内传遍网络。\n\n这段文字意在说明：",
   "options": [
    "人工智能降低了内容创作的门槛",
    "普通人也能制作高质量视频",
    "技术便利与信息真实性之间存在张力",
    "应禁止使用人工智能生成内容"
   ],
   "answer": 2,
   "explain": "文段先讲技术门槛降低带来的便利，用“与此同时”引出问题：真假难辨。重点在两者的张力。A、B只概括前半部分；D“禁止”属于过度推断。",
   "optionNotes": [
    "只概括了前半部分。",
    "只是便利的一个例子。",
    "正确。兼顾便利与真实性两方面。",
    "“禁止”过度推断。"
   ],
   "method": "中心理解：抓转折、因果、对策、尾句；选项必须包含主题词且不扩大不缩小",
