   "point": "yv-zhongxin",
   "difficulty": 2,
   "materialId": null,
   "stem": "在传统农业社会，人们通过节气安排农事，节气是生产生活的“时间表”。进入工业社会后，节气与生产的联系减弱，但它并没有消失，而是转化为一种文化记忆，提醒人们顺应自然、感受四季。\n\n这段文字主要介绍：",
   "options": [
    "如何传承二十四节气文化",
    "节气在传统农业社会的作用",
    "节气功能的转变及其文化意义",
    "工业社会对传统节气的冲击"
   ],
   "answer": 2,
   "explain": "文段按时间顺序讲节气从“生产时间表”到“文化记忆”的转变，重点在转变后的文化意义。A只讲传统社会；C只讲冲击；D“如何传承”文段未提。",
   "optionNotes": [
    "“如何传承”文段未提。",
    "只涉及前半部分。",
    "正确。概括了功能转变与文化意义。",
    "只涉及转折部分。"
   ],
