   "materialId": null,
   "stem": "有人认为，保护方言会妨碍普通话的推广。这种看法把两者对立起来了。事实上，方言与普通话并非此消彼长的关系：一个人完全可以既说好普通话，又保留自己的方言。方言中蕴含的地方文化和思维方式，恰恰是普通话难以替代的。\n\n作者对“保护方言会妨碍普通话推广”这一看法的态度是：",
   "options": [
    "不置可否",
    "赞成",
    "反对",
    "部分认同"
   ],
   "answer": 2,
   "explain": "“这种看法把两者对立起来了”“事实上……并非此消彼长”明确否定该看法。后文进一步说明方言的独特价值。因此作者态度是反对。",
   "optionNotes": [
    "作者态度明确。",
    "与“把两者对立起来”矛盾。",
    "正确。作者明确否定该看法。",
    "作者没有部分认同，而是否定。"
   ],
   "method": "中心理解：抓转折、因果、对策、尾句；选项必须包含主题词且不扩大不缩小",
