   "point": "yv-zhongxin",
   "difficulty": 3,
   "materialId": null,
   "stem": "很多人把“自律”理解为对自己狠一点：早起、健身、戒掉娱乐。但真正的自律，不是靠意志力硬扛，而是建立一套让自己“不必硬扛”的系统：把目标拆小、把环境布置好、把行动变成习惯。\n\n这段文字意在说明：",
   "options": [
    "娱乐会消磨人的意志",
    "自律需要强大的意志力",
    "自律的关键在于建立可持续的机制",
    "早起健身是自律的表现"
   ],
   "answer": 2,
   "explain": "文段先提出常见理解，用“但”转折，指出真正的自律是建立“不必硬扛”的系统，并列举拆目标、布置环境、养成习惯。主旨是机制而非意志力。A与文意相反；C是例子；D未提。",
   "optionNotes": [
    "文段未提娱乐的危害。",
    "与“不是靠意志力硬扛”矛盾。",
    "正确。转折后是主旨。",
    "只是被否定的例子。"
   ],
   "method": "中心理解：抓转折、因果、对策、尾句；选项必须包含主题词且不扩大不缩小",
