   "materialId": null,
   "stem": "古树名木被称为“活文物”。它们不仅记录着气候和土壤的变化，也承载着一个地方的历史记忆。保护古树，不能只是挂个牌子、围个栏杆，还需要专业的健康监测和生长环境修复。\n\n这段文字主要说明：",
   "options": [
    "古树保护需要专业化的措施",
    "挂保护牌的做法没有意义",
    "古树比文物更重要",
    "古树名木具有科研和文化价值"
   ],
   "answer": 0,
   "explain": "文段先讲古树的价值，尾句用“不能只是……还需要……”提出对策：专业监测和环境修复。主旨落在保护措施。A是铺垫；C曲解“不能只是”；D偷换比较。",
   "optionNotes": [
    "正确。尾句是对策。",
    "“没有意义”曲解文意。",
    "文段没有比较。",
    "是铺垫，非主旨。"
   ],
   "method": "中心理解：抓转折、因果、对策、尾句；选项必须包含主题词且不扩大不缩小",
