   "stem": "传统村落的保护，最怕“见物不见人”。把老房子修得再漂亮，如果原住民都搬走了，村落也就成了一个空壳。让村民在村里有活干、有钱赚，才是留住乡愁的根本。\n\n这段文字主要强调：",
