   "difficulty": 3,
   "materialId": null,
   "stem": "治理“饭圈”乱象，不能只靠平台删帖。粉丝群体的组织化、专业化程度越来越高，背后往往有商业力量推波助澜。只有切断利益链条，才能从根本上解决问题。\n\n这段文字意在强调：",
