   "stem": "将以下句子重新排列，语序正确的是：\n①这种“看不见的浪费”往往比看得见的浪费更严重\n②办公室里，打印纸只用了半面就被丢进废纸篓\n③节约资源，首先要让浪费变得“可见”\n④会议结束后，没喝完的瓶装水被留在桌上\n⑤但它们很少进入统计报表，也就难以引起重视",
