   "explain": "横线前讲“不断切换注意力”，横线后“因此”得出结论。横线处应承接“切换”并说明其代价，A最连贯。B、D与“因此”后的“断网”缺乏因果；C跳转到“安静环境”。",
   "optionNotes": [
    "是现象，不能解释“因此”。",
    "正确。承接“切换”，并引出“消耗资源”。",
    "只重复背景，未承接“切换”。",
    "话题跳转，与“断网”衔接弱。"
   ],
