   "difficulty": 2,
   "materialId": null,
   "stem": "沉没成本是指已经发生且无法收回的成本，理性决策时不应再受其影响。\n\n下列属于沉没成本的是：",
   "options": [
    "可以转卖给第三方的设备购置款",
    "为一场已经取消且无法退票的演出支付的票款",
    "为购买原材料预付的、可全额退还的订金",
    "尚未支付的项目预算"
   ],
   "answer": 1,
   "explain": "沉没成本的关键要件：①已经发生；②无法收回。A中票款已付且演出取消、不能退，符合两个要件。B订金可退、C尚未支付、D设备可转卖，都不满足“无法收回”。",
   "optionNotes": [
    "可转卖收回，不属于沉没成本。",
    "正确。已支付且无法退回。",
    "可全额退还，不属于无法收回。",
    "尚未发生，不构成成本。"
   ],
