   "difficulty": 2,
   "materialId": null,
   "stem": "边际效用递减是指在其他条件不变时，消费者连续增加某一种商品的消费，每增加一单位所带来的满足感增量逐渐减少。\n\n下列最符合边际效用递减的是：",
   "options": [
    "技术越先进，生产效率越高",
    "口渴时喝第一杯水很解渴，喝到第五杯时已不想再喝",
    "收入越高，缴纳的税款越多",
    "商品价格下降，购买量增加"
   ],
   "answer": 1,
   "explain": "边际效用递减强调“同一商品连续增加消费，新增满足感下降”。A中第1杯与第5杯的满足感变化正是此意。B是累进税；C是需求规律；D是技术进步。",
   "optionNotes": [
    "描述的是生产效率。",
    "正确。连续饮水，新增满足感下降。",
    "描述的是累进税率。",
    "描述的是价格与需求量的关系。"
   ],
