   "difficulty": 2,
   "materialId": null,
   "stem": "机会成本是指为了得到某种东西而放弃的其他选择中价值最高的那一项。\n\n下列属于机会成本的是：",
   "options": [
    "企业购买设备的支出",
    "家庭每月的房租支出",
    "大学生放弃工作去读研，所放弃的最高工资收入",
    "大学生读研期间缴纳的学费"
   ],
   "answer": 2,
   "explain": "机会成本的关键是“放弃的最高价值选择”。A中放弃的工作收入正是读研的机会成本。B、C、D都是实际支出（会计成本），不是放弃的替代选择。",
   "optionNotes": [
    "设备支出是实际成本。",
    "房租是实际支出。",
    "正确。放弃的最高工资即机会成本。",
    "学费是实际支出。"
   ],
